import valor from './main.js';

describe('valor final do pedido', () => {
  test('aplica o desconto antes de dobrar', () => {
    expect(valor).toBe(30);
  });
  test('exporta um número', () => {
    expect(typeof valor).toBe('number');
  });
});

import texto from './main.js';

describe('texto da linha mostrada', () => {
  test('junta textos e números com um espaço', () => {
    expect(texto).toBe('Vaga 12 livre');
  });
  test('não coloca vírgulas no texto final', () => {
    expect(texto.includes(',')).toBe(false);
  });
});

